import codecs
events = []
notes = []
secondary = ValueError('note lookup failed')
class Failure(ValueError):
    def __getattribute__(self, name):
        if name == '__notes__':
            events.append(input())
            return notes
        return super().__getattribute__(name)
failure = Failure('codec failed')
def transform(*args):
    raise failure
def search(name):
    if name == 'note_probe':
        return (transform, transform, None, None)
codecs.register(search)
try:
    codecs.encode('x', 'note-probe')
except BaseException as error:
    assert error is failure
    assert error.__context__ is None
else:
    assert False
assert events == ['service']
assert notes == ["encoding with 'note-probe' codec failed"]
print('verified')

